<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';import { AlertCircle, Radio, RefreshCw, Signal, SignalZero, Truck } from 'lucide-vue-next';import { api } from '../api';import PageHeader from '../components/PageHeader.vue';import { useSessionStore } from '../stores/session';
const session=useSessionStore(),loading=ref(false),error=ref(''),tab=ref('overview'),enterpriseId=ref('');const options=reactive<any>({enterprises:[]});const data=reactive<any>({summary:{currentOnline:0,todayOnline:0,currentOffline:0,average7d:0},trend:[],enterprises:[],abnormalEnterprises:[],items:[]});const isEnterprise=computed(()=>session.user?.portal==='ENTERPRISE');
async function loadOptions(){Object.assign(options,await api<any>('/operations/options'))}async function load(){loading.value=true;error.value='';try{const p=new URLSearchParams();if(enterpriseId.value)p.set('enterpriseId',enterpriseId.value);Object.assign(data,await api<any>(`/operations/online-monitor?${p}`))}catch(reason){error.value=reason instanceof Error?reason.message:'在线监测加载失败'}finally{loading.value=false}}watch(enterpriseId,load);onMounted(()=>Promise.all([load(),loadOptions()]));const fmtDay=(v:string)=>v.slice(5).replace('-','/');const age=(v?:string)=>{if(!v)return'无心跳';const m=Math.max(0,Math.round((Date.now()-new Date(v).getTime())/60000));return m<1?'刚刚':`${m} 分钟前`};
</script>
<template><PageHeader :title="isEnterprise?'在线情况':'在线监测'" description="统一查看当前在线、今日上线与近 7 日联网稳定性。"><el-select v-if="!isEnterprise" v-model="enterpriseId" clearable placeholder="全部企业" style="width:190px"><el-option v-for="item in options.enterprises" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button></PageHeader><div v-if="error" class="error-state"><strong>在线监测暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><template v-else><div class="operation-metrics" v-loading="loading"><div><Signal/><span>当前在线车辆</span><strong>{{data.summary.currentOnline}}</strong><small>实时连接</small></div><div><Truck/><span>今日上线车辆</span><strong>{{data.summary.todayOnline}}</strong><small>有上线记录</small></div><div><SignalZero/><span>当前离线车辆</span><strong>{{data.summary.currentOffline}}</strong><small>需关注心跳</small></div><div><Radio/><span>近 7 日在线率</span><strong>{{data.summary.average7d}}%</strong><small>车辆日均</small></div></div><el-tabs v-model="tab" class="monitor-tabs"><el-tab-pane label="在线概况" name="overview"><div class="monitor-grid"><section class="trend-card"><header><div><strong>在线率趋势</strong><span>最近 7 个自然日</span></div><b>{{data.summary.average7d}}%</b></header><div class="trend-chart"><div v-for="point in data.trend" :key="point.date"><span>{{point.onlineRate}}%</span><i><b :style="{height:`${point.onlineRate}%`}"></b></i><small>{{fmtDay(point.date)}}</small></div></div></section><section class="abnormal-card"><header><div><strong>在线率异常企业</strong><span>近 7 日均值低于 85%</span></div><AlertCircle :size="18"/></header><div v-for="item in data.abnormalEnterprises" :key="item.id" class="abnormal-row"><span><strong>{{item.name}}</strong><small>建议核查设备心跳与运营计划</small></span><b>{{item.onlineRate}}%</b></div><div v-if="!data.abnormalEnterprises.length" class="rail-empty">暂无异常企业</div></section></div><section class="enterprise-rate-card"><header><strong>企业在线率</strong><span>按近 7 日车辆在线数据计算</span></header><div class="enterprise-rate-grid"><div v-for="item in data.enterprises" :key="item.id"><span>{{item.name}}</span><strong>{{item.onlineRate}}%</strong><i><b :style="{width:`${item.onlineRate}%`}"></b></i></div></div></section></el-tab-pane><el-tab-pane label="在线车辆明细" name="details"><el-table :data="data.items" empty-text="暂无车辆"><el-table-column label="车辆" min-width="210"><template #default="{row}"><div class="identity-cell"><strong>{{row.name}}</strong><span>{{row.businessNo}}</span></div></template></el-table-column><el-table-column v-if="!isEnterprise" label="所属企业" min-width="210"><template #default="{row}">{{row.enterprise.name}}</template></el-table-column><el-table-column label="连接" width="90"><template #default="{row}"><span class="status-mark" :class="row.onlineStatus==='ONLINE'?'active':'inactive'"><i></i>{{row.onlineStatus==='ONLINE'?'在线':'离线'}}</span></template></el-table-column><el-table-column label="信号" width="100"><template #default="{row}">{{row.realtimeStatus?.signalStrength??0}}%</template></el-table-column><el-table-column label="电量" width="100"><template #default="{row}">{{row.realtimeStatus?.battery??'--'}}%</template></el-table-column><el-table-column label="最后心跳" min-width="130"><template #default="{row}">{{age(row.realtimeStatus?.heartbeatAt)}}</template></el-table-column></el-table></el-tab-pane></el-tabs></template>
</template>
